"""
Consolidated session tool — replaces scan.py and infra.py
"""
import asyncio
import json
import os

from core import cost as cost_tracker
from core import findings as findings_store
from core import logger as log
from core import session as scan_session
from mcp_server._app import mcp, _ensure_dict, _session_tools_called


@mcp.tool()
async def session(action: str, options: dict | None = None) -> str:
    """Scan lifecycle and infrastructure management.

    action  : start | complete | status | recovery | set_skill | set_step | start_kali | stop_kali | start_metasploit | stop_metasploit | pull_images | set_codebase

    start options:
      target, depth=standard (recon|standard|thorough), scope=[],
      out_of_scope=[], max_cost_usd=, max_time_minutes=, max_tool_calls=, skill=

    complete options:
      notes=

    status: returns current scan state (target, tools run, findings, cost, skill)

    recovery: returns compact recovery brief after context compaction — resume step,
              in-progress cells with technique notes, pending escalation leads, action list

    set_skill options:
      skill= (name of the active skill, e.g. "pentester", "ai-redteam")

    set_step options:
      step= (current workflow step, e.g. "5_nuclei_scan")

    set_codebase options:
      path= (absolute path to local codebase)

    start_kali, stop_kali, start_metasploit, stop_metasploit, pull_images: no options needed
    """
    opts = _ensure_dict(options) or {}

    if action == "start":
        return _do_start(opts)
    elif action == "complete":
        return await _do_complete(opts)
    elif action == "status":
        return _do_status()
    elif action == "set_skill":
        return _do_set_skill(opts)
    elif action == "set_step":
        return _do_set_step(opts)
    elif action == "start_kali":
        return await _do_start_kali()
    elif action == "stop_kali":
        return await _do_stop_kali()
    elif action == "start_metasploit":
        return await _do_start_metasploit()
    elif action == "stop_metasploit":
        return await _do_stop_metasploit()
    elif action == "pull_images":
        return await _do_pull_images()
    elif action == "set_codebase":
        return _do_set_codebase(opts)
    elif action == "recovery":
        return _do_recovery()
    elif action == "pre_chain":
        return _do_pre_chain(opts)
    else:
        return f"Unknown action '{action}'. Use: start, complete, status, recovery, pre_chain, set_skill, set_step, start_kali, stop_kali, start_metasploit, stop_metasploit, pull_images, set_codebase"


def _do_start(opts):
    _session_tools_called.clear()
    target = opts.get("target", "")

    # Coverage matrix lifecycle: only reset when the target changes.
    # Same target = keep matrix (resume interrupted scan or view completed results).
    # Different target = archive old matrix, then reset.
    from core.coverage import COVERAGE_FILE, _save as _cov_save, get_matrix
    from datetime import datetime, timezone
    import shutil

    prev = scan_session.get()
    prev_target = prev.get("target", "") if prev else ""
    cov = get_matrix()
    has_data = len(cov.get("matrix", [])) > 0

    if prev_target and prev_target != target and has_data:
        # Different target — archive the old matrix before resetting
        ts = datetime.now(timezone.utc).strftime("%Y%m%d_%H%M%S")
        archive_dir = COVERAGE_FILE.parent / "logs"
        archive_dir.mkdir(exist_ok=True)
        archive_path = archive_dir / f"coverage_matrix_{ts}.json"
        shutil.copy2(COVERAGE_FILE, archive_path)
        log.note(f"Coverage matrix archived to {archive_path.name} (previous target: {prev_target})")
        _cov_save({

        "cached_tokens": 0,
        "output_tokens": 0,
        "total_cost": 0.0,
        "tools_called": 0,
        "findings_count": 0,
    }

    # Count findings
    if findings_file.exists():
        try:
            data = json.loads(findings_file.read_text())
            findings = data if isinstance(data, list) else data.get("findings", [])
            cost["findings_count"] = len(findings)
        except Exception:
            pass

    # Count tool calls from session log
    if log_file.exists():
        try:
            content = log_file.read_text()
            cost["tools_called"] = content.count("[TOOL_CALL]")
        except Exception:
            pass

    return cost


# ---------------------------------------------------------------------------
# Flag checking
# ---------------------------------------------------------------------------

def check_flag(output_dir: Path, expected_flag: str) -> bool:
    """Search all output files + agent-smith artifacts for the flag."""
    search_paths = [
        output_dir,
        AGENT_SMITH_DIR / "findings.json",
        AGENT_SMITH_DIR / "pocs",
    ]

    for search in search_paths:
        if not search.exists():
            continue
        if search.is_file():
            try:
                if expected_flag in search.read_text(errors="ignore"):
                    return True
            except Exception:
                pass
        else:
            for f in search.rglob("*"):
                if not f.is_file():
                    continue
                try:
                    if expected_flag in f.read_text(errors="ignore"):
                        return True
                except Exception:
                    continue

    return False


# ---------------------------------------------------------------------------
# Cleanup agent-smith state between runs
# ---------------------------------------------------------------------------

def reset_agent_state() -> None:
    """Remove findings, pocs, and logs from the previous run."""
    for path in [
        AGENT_SMITH_DIR / "findings.json",
        AGENT_SMITH_DIR / "pocs",
        AGENT_SMITH_DIR / "logs" / "pentest.log",
        AGENT_SMITH_DIR / "coverage_matrix.json",
    ]:
        if path.is_file():
            path.unlink()
        elif path.is_dir():
            shutil.rmtree(path)


# ---------------------------------------------------------------------------
# Result writing
# ---------------------------------------------------------------------------

def save_result(
    run_dir: Path,
    benchmark: dict[str, Any],
    target_url: str,
    agent_result: dict[str, Any],
    flag_extracted: bool,
) -> None:
    run_dir.mkdir(parents=True, exist_ok=True)

    result = {
        "benchmark_id": benchmark["id"],
        "benchmark_name": benchmark["name"],
        "level": benchmark["level"],
        "tags": benchmark["tags"],
        "execution": {
            "started_at": agent_result["started_at"],
            "completed_at": agent_result["completed_at"],
            "duration_seconds": agent_result["duration_seconds"],
            # Setup time is infra overhead: docker build + compose up + HTTP wait.
            # Excluded from duration_seconds so comparisons are apples-to-apples.
            "setup_seconds": agent_result.get("setup_duration_seconds", 0),
            "total_seconds": round(
                agent_result["duration_seconds"] +
                agent_result.get("setup_duration_seconds", 0), 1
            ),
            "status": "solved" if flag_extracted else "unsolved",
            "error_message": None,
        },
        "target_url": target_url,
        "agent_execution": {
            "agent": "agent-smith",
            "exit_code": agent_result["exit_code"],
            "duration_seconds": agent_result["duration_seconds"],
            "resource_usage": agent_result["resource_usage"],
        },
        "evaluation": {
            "flag_extracted": flag_extracted,
        },
    }

    (run_dir / "result.json").write_text(json.dumps(result, indent=2) + "\n")


def copy_artifacts(run_dir: Path) -> None:
    """Copy agent-smith outputs (findings, pocs, logs) into the run directory."""
    artifacts_dir = run_dir / "artifacts"
    artifacts_dir.mkdir(exist_ok=True)

    for name in ["findings.json", "coverage_matrix.json"]:
        src = AGENT_SMITH_DIR / name
        if src.exists():
            shutil.copy2(src, artifacts_dir / name)

    for name in ["pocs", "logs"]:
        src = AGENT_SMITH_DIR / name
        if src.exists() and src.is_dir():
            dst = artifacts_dir / name
            if dst.exists():
                shutil.rmtree(dst)
            shutil.copytree(src, dst)


def write_evidence_package(
    run_dir: Path,
    benchmark: dict[str, Any],
    target_url: str,
    agent_result: dict[str, Any],
    flag_extracted: bool,
) -> None:
    """Write a self-contained EVIDENCE.md summarising the challenge run.

    Each per-challenge folder becomes a shareable evidence package:
      runs/run_XBEN-001-24/
        EVIDENCE.md           <- human-readable summary (this)
        result.json           <- machine-readable result
        outputs/              <- raw agent stdout/stderr
        artifacts/
          findings.json       <- all vulnerabilities found
          pocs/               <- Burp-ready .http files
          logs/pentest.log    <- full decision audit trail
          coverage_matrix.json
    """
    findings_file = run_dir / "artifacts" / "findings.json"
    findings: list[dict] = []
    if findings_file.exists():
        try:
            data = json.loads(findings_file.read_text())
            findings = data if isinstance(data, list) else data.get("findings", [])
        except Exception:
            pass

    # Find the exact line where the flag was captured
    flag_line = ""
    log_file = run_dir / "artifacts" / "logs" / "pentest.log"
    if log_file.exists():
        try:
            for line in log_file.read_text(errors="ignore").splitlines():
                if benchmark["expected_flag"] in line:
                    flag_line = line[:300]
                    break
        except Exception:
            pass

    pocs_dir = run_dir / "artifacts" / "pocs"
    pocs = sorted(f.name for f in pocs_dir.iterdir()) if pocs_dir.exists() else []

    usage = agent_result.get("resource_usage", {}) or {}
    status = "SOLVED" if flag_extracted else "UNSOLVED"
    duration = agent_result.get("duration_seconds", 0)
    cost = usage.get("total_cost", 0) or 0

    lines = [
        f"# {benchmark['id']} — {status}",
        "",
        f"**Challenge:** {benchmark['name']}",
        f"**Level:** {benchmark['level']}",
        f"**Tags:** `{', '.join(benchmark['tags'])}`",

